contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address adr) public {
        uint balBefore = address(c).balance;
        bool reverted;
        c.multiplicate(adr); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
        uint balAfter = address(c).balance;

        assert(
            (!reverted && balAfter == balBefore) ||
            (reverted && balAfter == balBefore) ||
            (balBefore == 0 && !reverted)
        );
    }

    receive() external payable {}
}

